import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {n} positive real numbers x_1, x_2, ..., x_{n} are chosen so that for every 1 <= k < m <= {n} the following parity-dependent pairwise constraints hold:\n- If k and m have the same parity, then x_k + x_m >= k m + {gamma}.\n- If k and m have opposite parity, then x_k + x_m >= k m + {delta}.\nDetermine the exact minimum possible value of S = x_1 + x_2 + ... + x_{n}. After solving, output your final value in the format: ### The final answer is: \\boxed{<value>}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose an even n >= 8
m = rng.randint(4, 60)  # so n = 2m in [8, 120]
n = 2 * m
# Choose delta >= 2 to ensure positivity in the constructive solution
delta = rng.randint(2, 8)
# Choose gamma in [1, delta] to enforce nontrivial same-parity constraints but maintain feasibility
gamma = rng.randint(1, delta)
return {'n': n, 'gamma': gamma, 'delta': delta}

    def verifier(assign):
# Validate assignment
try:
    n = assign['n']
    gamma = assign['gamma']
    delta = assign['delta']
except Exception:
    # Missing keys
    return (False, None)
# Type checks
if not (isinstance(n, int) and isinstance(gamma, int) and isinstance(delta, int)):
    # Types must be integers
    return (False, None)
# Domain checks for difficulty and feasibility
if n < 8 or n % 2 != 0:
    # Must be even and reasonably large to avoid trivial small cases
    return (False, None)
if delta < 2:
    # Ensure constructive positivity and nontriviality
    return (False, None)
if gamma < 1 or gamma > delta:
    # Enforce gamma in [1, delta] so same-parity constraints are nontrivial but dominated by opposite-parity ones
    return (False, None)
# Compute the asserted optimal value:
# For n = 2m, the optimal perfect matching (by rearrangement) is (1,2), (3,4), ..., (2m-1, 2m),
# each opposite-parity; since delta >= gamma, this matching maximizes the dual lower bound.
# Sum over k=1..m of [(2k-1)(2k) + delta] = sum of (4k^2 - 2k) + m*delta.
m = n // 2
# Compute sum_{k=1}^m (4k^2 - 2k) = 4 * sum k^2 - 2 * sum k
sum_k2 = m * (m + 1) * (2 * m + 1) // 6
sum_k = m * (m + 1) // 2
base = 4 * sum_k2 - 2 * sum_k
answer = base + m * delta
# Return as integer
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

